node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
// Check products table schema
const info = db.prepare(\"PRAGMA table_info(products)\").all();
console.log('products schema:', JSON.stringify(info, null, 2));
// Search for wireless mouse
const rows = db.prepare(\"SELECT * FROM products WHERE LOWER(name) LIKE '%wireless%mouse%' OR LOWER(name) LIKE '%m310%'\").all();
console.log('results:', JSON.stringify(rows, null, 2));
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check rt_variants for this product
const info = db.prepare(\"PRAGMA table_info(rt_variants)\").all();
console.log('rt_variants schema:', JSON.stringify(info, null, 2));

const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = 'PROD-FA0948'\").all();
console.log('rt_variants for PROD-FA0948:', JSON.stringify(variants, null, 2));

// Also check compatible products
const compat = ['PROD-B98D14','PROD-73FAB4'];
for (const pid of compat) {
  const p = db.prepare('SELECT product_id, name, brand, price FROM products WHERE product_id = ?').get(pid);
  console.log('Compatible product:', JSON.stringify(p));
}
"

